var __exports = AINOW['data/data-macedonian'] = AINOW['data/data-macedonian'] || {};
// Contains all prompts for the 'Macedonian' category.
const macedonianPrompts = [
    {"id":"mk-1","title":"Бизнис план за македонски МСП","prompt":"Вие сте искусен бизнис консултант со 15 години искуство во советување на мали и средни претпријатија во Македонија и регионот на Западен Балкан. Напишете детален бизнис план за отворање на органска фарма и агротуристичка дестинација во Полошкиот регион, со почетна инвестиција од 150.000 евра. Планот треба да вклучува: анализа на пазарот (локален и странски туристи, органски производи за извоз), финансиски проекции за 3 години (приходи, трошоци, точка на рентабилност), план за вработување (8-10 лица од локалната заедница), стратегија за добивање EU субвенции преку ИПАРД програмата, маркетинг план фокусиран на германскиот и швајцарскиот туристички пазар, и план за управување со ризици. Форматирајте го планот како извршен документ подготвен за презентација пред банки и инвеститори.","tags":["business","entrepreneurship","macedonia","agriculture"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-2","title":"Стратегија за EU интеграција на општини","prompt":"Вие сте експерт за европски интеграции со искуство во јавна администрација во земјите од Западен Балкан. Напишете стратешки документ за општини во Северна Македонија кои сакаат да ги усогласат своите локални политики со EU стандардите во рамките на Поглавјата 23 и 24 (правосудство, основни права, правда, слобода и безбедност). Документот треба да вклучи: преглед на тековниот напредок на земјата во пристапните преговори, конкретни чекори за локалните власти, примери од општини во Словенија и Хрватска кои поминале низ истиот процес, временска рамка за усогласување, и препораки за обука на општинските службеници. Документот да биде практичен и применлив за општини со помалку од 50.000 жители.","tags":["eu-integration","public-administration","policy","western-balkans"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-3","title":"Анализа на туристички потенцијал на регион","prompt":"Вие сте туристички консултант специјализиран за одржлив туризам во Југоисточна Европа. Направете детална анализа на туристичкиот потенцијал за следниот македонски регион: [Опишете го регионот — локација, природни и културни ресурси, тековна туристичка инфраструктура]. Анализата треба да опфати: SWOT анализа на туристичкиот сектор, идентификација на 5 клучни туристички производи (авантуристички, културен, гастрономски, верски, еко-туризам), анализа на конкуренцијата (Косово, Албанија, Бугарија), препораки за таргетирање на пазари, и предлог за туристички бренд на регионот. Вклучете и проценка на потребните инвестиции и можностите за финансирање преку ИПА фондови.","tags":["tourism","regional-development","marketing","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-4","title":"Подготовка за јавен тендер во Македонија","prompt":"Вие сте правен советник специјализиран за јавни набавки според македонскиот Закон за јавни набавки и EU директивите. Напишете комплетен водич за мало претпријатие кое прв пат учествува на јавен тендер во Македонија. Водичот треба да вклучи: чекор-по-чекор процес на регистрација во ЕСЈН (Електронски систем за јавни набавки), листа на задолжителни документи (тендерска документација, банкарска гаранција, потврди), најчести грешки при поднесување понуди, критериуми за оценување понуди (цена наспроти квалитет), права и обврски на добавувачот, и процедури за жалба во случај на спорни одлуки. Додадете практични совети за зголемување на конкурентноста на понудата.","tags":["procurement","legal","business","public-sector"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-5","title":"Дигитална трансформација на македонска компанија","prompt":"Вие сте консултант за дигитална трансформација со искуство во работа со македонски компании од производствениот сектор. Напишете сеопфатен план за дигитална трансформација за производствено претпријатие со 80 вработени и годишен приход од 2 милиони евра. Планот треба да опфати: процена на тековната дигитална зрелост, приоритетни области за дигитализација (ERP систем, дигитален маркетинг, автоматизација на производство, е-трговија), временска рамка во три фази (6, 12 и 24 месеци), буџетски план со реална проценка на трошоците за македонскиот пазар, план за обука на вработените, и мерки за сајбер безбедност. Наведете конкретни алатки и платформи достапни и применливи во македонскиот деловен контекст.","tags":["digital-transformation","technology","business","sme"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-6","title":"Стратегија за извоз на македонски производи","prompt":"Вие сте експерт за меѓународна трговија со длабоко познавање на македонската економија и регионалните пазари. Изработете стратегија за извоз на македонски прехранбени производи (вино, сирење, ајвар, органски зеленчук) на германскиот пазар. Стратегијата треба да вклучи: анализа на германскиот пазар за органски и специјалитети прехранбени производи, регулаторни барања за извоз во EU (санитарни, фитосанитарни, сертификати за потекло), логистички решенија и трошоци на транспорт, стратегија за влез на пазарот (дистрибутери, саеми, е-трговија), брендирање и пакување прилагодено за германскиот потрошувач, и временска рамка со конкретни чекори за прва година на извоз. Вклучете листа на клучни саеми и настани во Германија релевантни за македонските извозници.","tags":["export","trade","food","international-business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-7","title":"Реформа на образовниот систем — анализа","prompt":"Вие сте образовен експерт со искуство во реформи на образовни системи во земјите од Западен Балкан. Напишете аналитички документ за предизвиците и можностите за реформа на средното образование во Северна Македонија. Документот треба да ги опфати: тековните структурни слабости (застарени наставни програми, недостиг на практична настава, јаз помеѓу образованието и пазарот на труд), компаративна анализа со образовните системи на Финска и Естонија, препораки за модернизација на наставните методи (STEM образование, критичко размислување, дигитални вештини), предлог за зајакнување на дуалното образование по германскиот модел, финансиски импликации на реформите, и план за вклучување на работодавачите во дизајнирање на наставните програми.","tags":["education","reform","policy","youth"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-8","title":"Агробизнис стратегија за ИПАРД финансирање","prompt":"Вие сте агробизнис консултант специјализиран за европски фондови и земјоделска политика во Македонија. Напишете детална апликација и стратегија за добивање финансирање преку ИПАРД III програмата за модернизација на земјоделско стопанство. Документот треба да вклучи: опис на проектот (набавка на современа земјоделска механизација, наводнувачки систем, ладилници за складирање), образложение за потребата и влијанието врз конкурентноста, финансиска анализа (вкупни трошоци, побаран грант, сопствено учество), план за имплементација со рокови, очекувани резултати мерливи со индикатори, и план за одржливост по завршување на проектот. Вклучете и советување за избегнување на најчестите причини за одбивање на ИПАРД апликации.","tags":["agriculture","eu-funds","ipard","rural-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-9","title":"Комуникациска стратегија за локална самоуправа","prompt":"Вие сте советник за комуникации специјализиран за јавна администрација и локална самоуправа во Македонија. Напишете годишна комуникациска стратегија за општина со 30.000 жители. Стратегијата треба да опфати: анализа на тековната комуникација со граѓаните и идентификација на слабостите, дефинирање на целни групи (млади, бизнис заедница, постари граѓани, дијаспора), план за дигитална комуникација (веб-страница, социјални мрежи, мобилна апликација), план за директна комуникација (јавни расправи, билтени, информативни настани), кризна комуникација — процедури и одговорности, мерење на ефективноста на комуникацијата, и буџет со реални трошоци за македонски услови.","tags":["public-administration","communication","local-government","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-10","title":"Финансиска анализа за МСП — пристап до кредити","prompt":"Вие сте финансиски советник со специјализација за мали и средни претпријатија во Македонија. Напишете практичен водич за МСП кои сакаат да добијат банкарски кредит или финансирање преку Развојната банка на Македонија. Водичот треба да опфати: видови финансирање достапни за МСП (банкарски кредити, кредитни линии на РБМ, гаранциски фонд, ризичен капитал), услови и критериуми за квалификација, потребна документација (финансиски извештаи, бизнис план, колатерал), чекор-по-чекор процес на аплицирање, совети за зајакнување на кредитниот профил, алтернативни извори на финансирање (EU грантови, crowd-funding, business angels), и споредба на каматни стапки и услови на главните банки во Македонија.","tags":["finance","sme","banking","investment"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-11","title":"Основање на startup во Македонија — правен водич","prompt":"Вие сте правник специјализиран за трговско право и стартап екосистем во Македонија. Напишете комплетен правен водич за основање на технолошки стартап во Македонија. Водичот треба да вклучи: споредба на правните форми (ДООЕЛ, АД, ДОО) со предности и недостатоци за стартапи, чекор-по-чекор процедура за регистрација во Централниот регистар, даночни обврски и олеснувања за иновативни компании (Технолошки развоен парк), заштита на интелектуална сопственост (патенти, трговски марки, авторски права) во македонскиот и EU контекст, работни правни односи и вработување на странски државјани, договори со инвеститори (term sheet, shareholders agreement), и процедури за добивање статус на иновативна компанија. Вклучете конкретни временски рокови и трошоци за секој чекор.","tags":["legal","startup","entrepreneurship","tech"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-12","title":"Маркетинг план за македонски туристички производ","prompt":"Вие сте маркетинг стратег специјализиран за туристичка индустрија во Македонија и регионот. Изработете годишен маркетинг план за промоција на Охрид и Охридското Езеро на меѓународниот туристички пазар. Планот треба да опфати: анализа на тековната позиција на Охрид во регионалната и глобална конкуренција, дефинирање на целни пазари (Скандинавија, Германија, Холандија, земјите од Залив), дигитален маркетинг план (SEO, социјални мрежи, influencer маркетинг, Google Ads), план за настап на меѓународни туристички саеми (ITB Берлин, WTM Лондон), стратегија за партнерства со туроператори, буџет со приоритизација на активности, и KPI индикатори за мерење на успехот. Посветете посебно внимание на промовирање на одржлив и одговорен туризам.","tags":["tourism","marketing","ohrid","international"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-13","title":"Анализа на пазарот на труд во Македонија","prompt":"Вие сте економист специјализиран за пазар на труд и вработеност во земјите на Западен Балкан. Напишете сеопфатна анализа на пазарот на труд во Северна Македонија со фокус на предизвиците и можностите во наредните 5 години. Анализата треба да опфати: тековни трендови (стапка на невработеност, неформална економија, структурна невработеност), анализа на одливот на мозоци и нговото влијание на македонската економија, недостиг на работна сила во клучни сектори (ИТ, здравство, градежништво), ефикасност на активните политики за вработеност на АВРМ, препораки за задржување на млади таленти, стратегија за привлекување на дијаспората, и компаративна анализа со пазарите на труд во земјите членки на EU со слична историја (Бугарија, Романија).","tags":["labor-market","economics","employment","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-14","title":"План за општинска енергетска ефикасност","prompt":"Вие сте консултант за енергетика и одржлив развој со искуство во општини во Македонија. Напишете акционен план за зголемување на енергетската ефикасност во јавните згради на општина со 25.000 жители. Планот треба да вклучи: енергетска ревизија на јавните згради (училишта, детски градинки, административни згради), приоритизација на интервенции по трошоци и заштеди (термоизолација, нови прозори, LED осветлување, соларни панели), финансиски модел со проценка на заштеди и рок на враќање на инвестицијата, можности за финансирање (Ковенант на градоначалниците, ELENA инструмент, ЕКО фонд на РМ), план за имплементација по фази, и процедура за јавни набавки за енергетски услуги (EPC договори). Вклучете конкретни примери од општини во Македонија кои успешно имплементирале слични мерки.","tags":["energy-efficiency","environment","local-government","sustainability"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-15","title":"Стратегија за развој на IT сектор во Македонија","prompt":"Вие сте технолошки стратег со искуство во развој на дигитални екосистеми во земјите на Западен Балкан. Напишете стратегија за зајакнување на IT секторот во Македонија со цел да стане регионален центар за аутсорсинг и развој на софтвер. Стратегијата треба да опфати: анализа на тековниот IT сектор (број на компании, приход, вработени, клучни играчи), конкурентни предности на Македонија (образован кадар, ниски трошоци, временска зона, јазични вештини), недостатоци и пречки за раст (одлив на таленти, недостиг на капитал, бирократија), конкретни мерки за унапредување (даночни олеснувања, технолошки паркови, партнерства со универзитети), стратегија за привлекување на странски ИТ компании, план за развој на дигиталните вештини на работната сила, и мерки за успех со временска рамка.","tags":["technology","it","digital","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-16","title":"Водич за здравствен систем во Македонија","prompt":"Вие сте здравствен консултант со длабоко познавање на македонскиот здравствен систем и европските стандарди за здравствена заштита. Напишете сеопфатен водич за пациентите за навигација низ македонскиот здравствен систем. Водичот треба да опфати: структурата на здравствениот систем (примарна, секундарна, терцијарна здравствена заштита), права на пациентите според македонскиот закон, постапка за запишување кај матичен лекар и упатување на специјалист, листи на чекање и начини за нивно скратување, здравствено осигурување (задолжително и доброволно), постапки за итна медицинска помош, пристап до лекови и нивна рефундација, и разлики во достапноста на здравствената заштита меѓу урбаните и руралните средини. Вклучете и препораки за подобрување на комуникацијата помеѓу пациентот и лекарот.","tags":["healthcare","public-health","patients","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-17","title":"Регионална соработка во Западен Балкан","prompt":"Вие сте аналитичар на надворешна политика специјализиран за регионална соработка во Западен Балкан. Напишете аналитички извештај за можностите и пречките за продлабочување на регионалната економска соработка меѓу земјите на Западен Балкан во рамките на иницијативата Отворен Балкан. Извештајот треба да опфати: тековна состојба на трговската размена меѓу земјите, анализа на успесите и неуспесите на Отворен Балкан (слободно движење на работна сила, роби и услуги), компаративна анализа со процесот на формирање на EU единствен пазар, политички пречки и националистички тензии кои ја попречуваат соработката, препораки за поефективни механизми за регионална соработка, и улогата на EU, САД и Кина во регионот. Базирајте се на конкретни податоци и факти.","tags":["regional-cooperation","western-balkans","politics","trade"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-18","title":"Наставна програма за дигитална писменост","prompt":"Вие сте образовен дизајнер специјализиран за дигитални вештини и образование во Македонија. Создадете наставна програма за курс по дигитална писменост за ученици од 7-мо до 9-то одделение во македонските основни училишта. Програмата треба да вклучи: цели на учење усогласени со европската DIGCOMP рамка, распоред на часови (30 часа годишно) со теми и активности, методологија (проектна настава, групна работа, практични задачи), содржини (безбедност на интернет, критичко оценување на информации, основи на програмирање, дигитална креативност), предлог за оценување на постигнувањата, препораки за дигитална опрема потребна во училница, и план за обука на наставниците. Програмата треба да биде применлива и во училишта со ограничени ресурси.","tags":["education","digital-literacy","curriculum","youth"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-19","title":"Стратегија за развој на руралните подрачја","prompt":"Вие сте консултант за рурален развој со искуство во програмирање и имплементација на EU фондови во Македонија. Напишете стратегија за одржлив развој на рурална општина во источна Македонија која се соочува со депопулација и економска стагнација. Стратегијата треба да опфати: дијагноза на тековната состојба (демографски тренд, економска структура, инфраструктура), визија и стратешки цели за 2030 година, приоритетни интервенции (агробизнис, рурален туризам, обновлива енергија, дигитализација), финансиски план со идентификација на извори (ИПАРД, ИПА, национален буџет, општини), план за вклучување на локалната заедница, мерење на напредокот со конкретни индикатори, и план за привлекување на млади назад во руралните средини преку стипендии и субвенции.","tags":["rural-development","regional-policy","agriculture","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-20","title":"Анализа на македонскиот винарски сектор","prompt":"Вие сте агро-економист и консултант за виното специјализиран за македонскиот пазар. Напишете детална анализа на македонскиот винарски сектор со препораки за зголемување на извозот и подобрување на меѓународниот имиџ. Анализата треба да опфати: преглед на македонскиот винарски сектор (површини, сорти, производство, број на визери), анализа на извозот (главни пазари, тренд на раст, ценовно позиционирање), конкурентни предности (климатски услови, автохтони сорти Вранец и Тиквеш, трошоци на производство), слабости (имиџ, маркетинг, стандарди за квалитет), споредба со успешните балкански вина (Грција, Хрватска, Романија), и конкретни препораки за Macedonia Wine Brand стратегија, вклучително промоција на еко-туризмот во Тиквешкиот регион.","tags":["wine","agriculture","export","branding"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-21","title":"Правен водич за работни односи во Македонија","prompt":"Вие сте трудово-правен советник со 10 години искуство во македонското работно право. Напишете практичен водич за работодавачи — мали и средни претпријатија — за правилно управување со работните односи согласно Законот за работни односи на Македонија. Водичот треба да опфати: склучување на договор за вработување (задолжителни елементи, видови договори), пробна работа и нејзините ограничувања, права и обврски на работодавачот и работникот, постапка за дисциплинска одговорност и отказ (заштита на работникот, откажување на договор), платен и неплатен одмор — правила и исклучоци, заштита при бременост и родителство, работа преку агенции и privremeni договори, надомест за отказ и решавање на работни спорови, и инспекциски надзор на Државниот инспекторат за труд.","tags":["legal","labor-law","hr","business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-22","title":"Стратегија за млади претприемачи во Македонија","prompt":"Вие сте ментор и поддржувач на претприемаштвото со искуство во работа со млади во Македонија и регионот. Напишете практичен водич за млади (18-30 години) кои сакаат да започнат свој бизнис во Македонија. Водичот треба да опфати: ментален склоп и карактеристики на успешниот претприемач, идентификација на бизнис идеи базирани на локалните можности, валидација на идеи (lean startup методологија), расположиви програми за поддршка (ФИТР, Агенција за вработување — самовработување, Junior Achievement, Start Up Macedonia), финансирање за млади (микро-кредити, грантови за млади претприемачи), изградба на мрежа и ментори, и реални приказни за успешни млади македонски претприемачи. Пишувајте во охрабрувачки, неформален тон наменет за млади читатели.","tags":["entrepreneurship","youth","startup","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-23","title":"Водич за пристап до EU фондови за општини","prompt":"Вие сте консултант за EU фондови со повеќе од 12 години искуство во управување со проекти финансирани од Европската унија во Македонија. Напишете детален водич за општини кои сакаат да аплицираат за финансирање преку ИПА III инструментот. Водичот треба да вклучи: структурата на ИПА III и достапните компоненти за општини, процесот на идентификација на соодветни повици за проекти, градење на проектна идеја и нејзино усогласување со приоритетите на програмата, партнерства и форматите на конзорциум, барања за административен капацитет на апликантот, пишување на проектна апликација (логичка матрица, наратив, буџет), управување со проектот по одобрување (извештаи, набавки, ревизија), и список на консултантски компании и мрежи кои нудат поддршка за општини во Македонија.","tags":["eu-funds","local-government","ipa","project-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-24","title":"Анализа на македонскиот здравствен систем","prompt":"Вие сте здравствено-политички аналитичар со специјализација за реформи на здравствените системи во Западен Балкан. Напишете сеопфатна анализа на македонскиот здравствен систем со фокус на потребните реформи за достигнување на EU стандардите. Анализата треба да опфати: структура на финансирање на здравствениот систем (јавно-приватна поделба, ФЗОМ), клучни показатели за здравје на популацијата наспроти EU просек, анализа на примарната здравствена заштита и предизвиците во руралните области, капацитет на болничкиот систем (опрема, кадар, листи на чекање), предизвици со корупција и неформални плаќања, искуства од земји кои успешно ги реформирале своите системи (Естонија, Словенија), и конкретни препораки за реформи со приоритизација и временска рамка.","tags":["healthcare","reform","policy","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-25","title":"Промоција на македонскиот јазик и култура","prompt":"Вие сте културолог и лингвист специјализиран за македонскиот јазик и неговото место во словенската јазична група. Напишете сеопфатен есеј за значењето и уникатноста на македонскиот јазик и неговата улога во зачувувањето на македонскиот национален идентитет. Есејот треба да опфати: историски развој на македонскиот литературен јазик (Мисирков, кодификацијата во 1945), место на македонскиот во групата на јужнословенски јазици, дијалектно богатство и регионалните варијации, влијанието на турски, грчки и арапски јазик врз македонскиот вокабулар, предизвиците на дигиталното доба за македонскиот јазик, македонската литература — Рацин, Конески, Шопов, Матевски, и значењето на македонскиот јазик за дијаспората во светот. Пишувајте живо и пристапно.","tags":["language","culture","identity","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-26","title":"Стратегија за е-трговија за македонски бизниси","prompt":"Вие сте консултант за е-трговија со специјализација за малите пазари во Источна Европа. Напишете стратегија за македонско претпријатие кое сака да ги продава своите производи преку онлајн канали — и на домашниот и на меѓународниот пазар. Стратегијата треба да опфати: анализа на македонскиот е-трговски пазар (пенетрација, навики на потрошувачите, платежни методи), избор на платформа (Shopify, WooCommerce, Shopify + Emag.mk), поставување на логистика и испорака (Македонска Пошта, приватни куриери, меѓународна испорака), решенија за онлајн плаќање прилагодени за македонскиот пазар, дигитален маркетинг за е-трговија (Facebook Ads, Google Shopping, SEO), правни и даночни аспекти на е-трговија во Македонија, и план за скалирање на бизнисот на регионалниот пазар (Балкан). Вклучете конкретни примери на успешни македонски онлајн продавници.","tags":["e-commerce","digital","marketing","sme"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-27","title":"Управување со проект по методологија на ЕУ","prompt":"Вие сте проектен менаџер со PMP сертификат и искуство во управување со EU финансирани проекти во Македонија. Напишете водич за управување со проект финансиран од Европската унија, вклучувајќи ги специфичните барања на ЕУ. Водичот треба да опфати: фази на проектен циклус (идентификација, формулација, имплементација, евалуација), изработка на логичка матрица (Logframe), планирање на активности (Gantt chart, WBS), управување со буџет и финансиски извештаи по EU барања, системи за набавки (EU тендерски правила), известување до донаторот (нарративни и финансиски извештаи), управување со ризици во проекти, видливост и комуникација (EU брендинг правила), и ревизија на проекти. Дадете практични совети за избегнување на најчестите пропусти во EU проекти.","tags":["project-management","eu-funds","administration","methodology"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-28","title":"Водич за македонска гастрономија","prompt":"Вие сте гастрономски новинар и кулинарски историчар специјализиран за балканската кујна. Напишете богат гастрономски водич за македонската кујна кој може да се користи за промоција на Македонија во туристички цели и за дипломатски претставувања. Водичот треба да опфати: историски и културни корени на македонската гастрономија (влијание на отоманската, грчката и српската кујна), регионалните специјалитети (тавче гравче, мастика од Демир Капија, кожани пипер, струшки ракија), македонски вина и ракии со нивните географски ознаки, рецепти за 10 иконски македонски јадења со инструкции, традицијата на македонскиот мезе и ракиски ритуали, современата македонска гастрономска сцена (ресторани, готвачи), и препораки за гастрономски тури низ Македонија.","tags":["gastronomy","culture","tourism","food"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-29","title":"Корпоративна општествена одговорност во Македонија","prompt":"Вие сте консултант за корпоративна општествена одговорност (КОО) со искуство во работа со македонски компании. Напишете стратегија за КОО за средно претпријатие со 150 вработени кое работи во прехранбената индустрија во Македонија. Стратегијата треба да опфати: анализа на очекувањата на засегнатите страни (вработени, потрошувачи, добавувачи, локална заедница, регулатори), приоритетни КОО области (животна средина, вработување, добавувачки синџир, заедница), конкретни иницијативи со цели и буџет, комуникација на КОО активностите (годишен извештај за одржливост, социјални мрежи), усогласување со UN Целите за одржлив развој (SDGs), и примери од македонски компании кои успешно имплементирале КОО програми. Нагласете врска меѓу КОО и бизнис резултатите.","tags":["csr","sustainability","business","community"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-30","title":"Анализа на инвестициска клима во Македонија","prompt":"Вие сте економски аналитичар специјализиран за директни странски инвестиции во Западен Балкан. Напишете аналитички извештај за инвестициската клима во Северна Македонија наменет за странски инвеститори. Извештајот треба да опфати: макроекономски показатели (GDP, инфлација, дефицит, долг), регулаторна рамка за странски инвестиции (Законот за трговски друштва, ТИРЗС), даночен систем и споредба со регионот (данок на добивка, ДДВ, придонеси), достапна работна сила и трошоци на трудот, инфраструктурна поврзаност (патна, железничка, воздушна), слободни економски зони и нивни придобивки, ризици (политичка стабилност, верба на правото, корупција), и конкретни примери на успешни странски инвестиции во Македонија (Johnson Controls, Kemet, Rembrandtin). Документот да биде базиран на актуелни статистички податоци.","tags":["investment","economics","fdi","business-climate"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-31","title":"Обука за јавно говорење на македонски","prompt":"Вие сте тренер за јавно говорење и комуникациски вештини со долгогодишно искуство во работа со македонски менаџери и политичари. Напишете структуриран програм за обука по јавно говорење на македонски јазик наменет за менаџери на средно ниво. Програмата треба да вклучи: принципи на ефективна комуникација и убедување, структурирање на говор (увод, тело, заклучок), техники за контролирање на трема и анксиозност, користење на гласот, паузите и говорот на телото, подготовка за презентации пред бројна публика, вештини за одговарање на прашања и справување со тешка публика, и 10 практични вежби со конкретни упатства. Вклучете примери на говорнички грешки карактеристични за македонскиот говорен контекст и совети за нивно надминување.","tags":["communication","public-speaking","training","leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-32","title":"Стратегија за развој на кадри во компанија","prompt":"Вие сте HR стратег со искуство во управување со човечки ресурси во македонски компании. Напишете стратегија за развој и задржување на кадри за компанија со 100 вработени во ИТ секторот во Македонија. Стратегијата треба да опфати: анализа на тековните предизвици со кадри (одлив на таленти, конкуренцијата со странски компании кои вработуваат онлајн), систем за перформанс менаџмент прилагоден за македонска работна култура, план за обука и развој на вештини (техничке и меки вештини), систем за компензации и бенефиции конкурентен на македонскиот пазар, стратегија за employer branding за привлекување млади таленти, мерки за работна рамнотежа живот-работа, и план за сукцесија на клучни позиции. Вклучете конкретни примери и алатки применливи во македонски услови.","tags":["hr","talent-management","strategy","business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-33","title":"Водич за македонска дијаспора — инвестирање во Македонија","prompt":"Вие сте финансиски и правен советник специјализиран за поврзување на македонската дијаспора со инвестициски можности во Македонија. Напишете практичен водич за македонски државјани кои живеат во странство и сакаат да инвестираат во Македонија. Водичот треба да опфати: правни форми за инвестирање (купување имот, основање бизнис, портфолио инвестиции), даночни импликации за нерезиденти во Македонија и нивниот однос со државата на живеење, постапка за отворање банкарска сметка во Македонија за нерезиденти, државни програми за поддршка на инвестициите на дијаспората, сектори со голем потенцијал за инвестиции (некретнини, туризам, ИТ, земјоделство), ризици и мерки на претпазливост, и контакти на институции кои нудат поддршка (МИРСМ, Агенција за странски инвестиции). Пишувајте јасно и практично.","tags":["diaspora","investment","macedonia","finance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-34","title":"Анализа на јавниот сектор и антикорупциски мерки","prompt":"Вие сте аналитичар за јавна политика и борба против корупција со искуство во работа со институциите во Македонија. Напишете аналитички документ за состојбата со корупцијата во Македонија и препораки за ефективни антикорупциски мерки. Документот треба да опфати: актуелна состојба (Corruption Perceptions Index, EU извештаи за напредок), секторска анализа на корупција (јавни набавки, судство, здравство, образование), правна рамка и институционален капацитет (ДКСК, ЈАВНО ОБВИНИТЕЛСТВО), компаративна анализа со успешни антикорупциски реформи на Балканот (пример Грузија, Естонија), конкретни препораки за зголемување на транспарентноста (дигитализација на јавни услуги, звиждачи), и улогата на гражданското општество и медиумите во борбата против корупција. Документот да биде базиран на конкретни докази и податоци.","tags":["anti-corruption","governance","policy","public-sector"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-35","title":"Е-влада и дигитализација на јавни услуги","prompt":"Вие сте консултант за е-влада и дигитална трансформација на јавниот сектор со искуство во Македонија и регионот. Напишете детален план за дигитализација на административните услуги на една министерство во Македонија. Планот треба да опфати: инвентар на тековни административни услуги и нивна комплексност, приоритизација на услуги за дигитализација по критериум на фреквентност и важност за граѓаните, техничка архитектура на системот (единствена точка на пристап, автентикација, дигитален потпис), правна рамка (Закон за е-влада, Закон за електронски потпис), план за миграција на постоечките податоци, обука на вработените, комуникациска кампања кон граѓаните, и мерење на задоволството на корисниците. Наведете конкретни примери на успешни е-влада решенија во регионот (Естонија, Грузија, Србија).","tags":["e-government","digital","public-administration","technology"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-36","title":"Анализа на конкурентноста на македонскиот текстилен сектор","prompt":"Вие сте индустриски аналитичар специјализиран за текстилната и облекувачката индустрија во Македонија. Напишете аналитички извештај за конкурентноста на македонскиот текстилен и облекувачки сектор во контекст на глобалните промени во синџирите на снабдување. Извештајот треба да опфати: преглед на секторот (број на компании, вработени, извоз, главни пазари), конкурентни предности (лон-работа, географска близина до EU, квалитет на изработка), закани (конкуренција од Азија, раст на трошоците на трудот, автоматизација), можности за преминување кон повисока вредносна верига (сопствен бренд, дизајн, одржлива мода), препораки за политики за поддршка на секторот, и стратегија за привлекување на европски брендови со повисоко маржи. Вклучете конкретни примери на македонски компании кои успешно го направиле овој премин.","tags":["textile","industry","export","competitiveness"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-37","title":"Планирање на одржлив еко-туризам","prompt":"Вие сте консултант за еко-туризам и одржлив развој со искуство во заштитени природни подрачја во Македонија. Напишете детален план за развој на еко-туризам во националниот парк или заштитено подрачје: [Наведете го националниот парк или заштитено подрачје и неговите клучни карактеристики]. Планот треба да опфати: инвентаризација на природните и културните ресурси, процена на носивиот капацитет на подрачјето, дизајн на 5 еко-туристички производи (пешачки патеки, набљудување птици, кампување, едукативни тури), инфраструктурни потреби (основни, не-инвазивни), систем за управување со посетителите, партнерства со локалните заедници и поделба на приходите, маркетинг стратегија, и план за мониторинг на влијанието врз животната средина. Усогласете го планот со принципите на GSTC (Глобален совет за одржлив туризам).","tags":["eco-tourism","sustainability","nature","regional-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-38","title":"Подготовка на CV и мотивационо писмо за EU институции","prompt":"Вие сте кариерен советник специјализиран за вработување во EU институции и меѓународни организации. Напишете комплетен водич за македонски државјани кои сакаат да аплицираат за работа во EU институциите (Европска комисија, Европски парламент, EU агенции). Водичот треба да опфати: форматот на Europass CV и неговите специфики, пишување на мотивационо писмо по стандардите на EU институциите, постапката за EPSO конкурси (компетенциски тестови, центар за проценка), потребни квалификации и јазични вештини, стипендии и програми за стажирање (Blue Book стаж, Schuman стаж), препораки за зајакнување на профилот (волонтерство, меѓународно искуство, јазици), и мрежи за поврзување со Македонци вработени во EU институциите.","tags":["career","eu-institutions","employment","education"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-39","title":"Стратегија за развој на социјалното претпријатие","prompt":"Вие сте консултант за социјална економија и социјално претпријатие со искуство во земјите на Западен Балкан. Напишете стратегија за основање и развој на социјално претпријатие во Македонија кое вработува лица со попреченост. Стратегијата треба да опфати: правна рамка за социјални претпријатија во Македонија (Закон за социјалното претпријатие), бизнис модели прилагодени за социјални претпријатија, финансирање (Министерство за труд, EU фондови, донации, приходи од пазарот), управување со специфичните предизвици при вработување на лица со попреченост, партнерства со институции (центри за социјална работа, општини, здравствени установи), маркетинг кој ги истакнува социјалните вредности, и план за постигнување на финансиска одржливост. Вклучете конкретни примери на успешни социјални претпријатија во регионот.","tags":["social-enterprise","inclusion","entrepreneurship","community"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-40","title":"Управување со мултикултурна средина во бизнисот","prompt":"Вие сте консултант за организациска култура и управување со разновидност со искуство во мултиетничка бизнис средина во Македонија. Напишете практичен водич за менаџери на компании со мултиетнички тим во Македонија (македонски, албански, турски, ромски вработени). Водичот треба да опфати: разбирање на интеркултурната динамика во македонскиот контекст, комуникациски стратегии прилагодени за мултикултурна средина, управување со религиски и културни разлики (празници, молитвено време, исхрана), превенција на конфликти базирани на етничка основа, изградба на инклузивна организациска култура, законски барања за рамноправност и недискриминација во Македонија, и студии на случај на успешни мултиетнички компании во Македонија. Пишувајте со почит и конструктивен тон.","tags":["diversity","management","culture","business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-41","title":"Развој на национален туристички бренд на Македонија","prompt":"Вие сте стратег за брендирање на дестинации со меѓународно искуство и длабоко познавање на Македонија. Напишете стратегија за развој и промоција на националниот туристички бренд на Македонија на меѓународните пазари. Стратегијата треба да опфати: анализа на тековната перцепција на Македонија кај странски туристи (силни и слаби страни на имиџот), идентификација на уникатните вредности на македонскиот туристички производ, дефиниција на бренд идентитет и brand messaging, визуелен идентитет и комуникациски материјали, дигитална маркетинг стратегија (веб-страница, социјални мрежи, YouTubers и travel bloggers), план за присуство на клучни меѓународни туристички саеми, партнерства со авиокомпании за воведување нови директни летови, и буџет за имплементација. Земете ги предвид и политичките чувствителности поврзани со употребата на имиња и симболи.","tags":["tourism","branding","marketing","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-42","title":"Водич за пишување грантови за НВО","prompt":"Вие сте искусен пишувач на грантови со над 10 години искуство во граѓанскиот сектор во Македонија. Напишете практичен водич за претставници на НВО кои сакаат да пишуваат успешни апликации за грантови. Водичот треба да опфати: разбирање на донаторскиот пејзаж во Македонија (EU, USAID, Амбасади, домашни донатори), идентификација на соодветни повици и усогласување на проектните идеи, структура на успешна апликација (проблем, цели, активности, резултати, влијание), пишување на убедлив наратив — јасен и конкретен, буџетирање на проектот (реалистично, детализирано, оправдано), вообичаени грешки кои водат до одбивање, управување со проектот по одобрување (известување, видливост, финансии), и изградба на долгорочни односи со донатори. Вклучете примери на добро и лошо пишување на апликации.","tags":["ngo","grants","civil-society","fundraising"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-43","title":"Стратегија за климатски промени за македонски општини","prompt":"Вие сте консултант за климатска политика и одржлив развој специјализиран за локалната самоуправа во Македонија. Напишете локален акционен план за климатска акција за општина со 40.000 жители. Планот треба да опфати: процена на климатските ризици за општината (поплави, суши, топлотни бранови), инвентар на емисии на стакленички гасови во општината, цели за намалување на емисии усогласени со Парискиот договор, приоритетни мерки за намалување (транспорт, енергија, отпад), мерки за прилагодување кон климатските промени (зелена инфраструктура, управување со води), финансирање преку Зелен климатски фонд и EU програми, план за ангажирање на граѓаните, и систем за мониторинг и известување. Осигурете усогласување со Националниот план за климатска акција на Македонија.","tags":["climate-change","environment","local-government","sustainability"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-44","title":"Стратегија за управување со отпад во македонска општина","prompt":"Вие сте консултант за управување со отпад и животна средина со искуство во Македонија. Напишете стратегија за управување со комунален отпад за општина во согласност со EU директивите за отпад и македонското законодавство. Стратегијата треба да опфати: анализа на тековниот систем за собирање и одлагање на отпад, цели за зголемување на стапката на рециклирање (согласно EU директивите), план за воведување на разделено собирање отпад (4 фракции), систем за компостирање на органски отпад, едукациска кампања за граѓаните, економски инструменти (принципот „загадувачот плаќа\"), управување со депонии и план за санација, регионална соработка помеѓу општини, и финансиски план за имплементација. Вклучете добри практики од македонски општини кои веќе имаат напредок во оваа област.","tags":["waste-management","environment","local-government","sustainability"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-45","title":"Водич за медиумска писменост за наставници","prompt":"Вие сте медиумски едукатор со искуство во развој на образовни програми за медиумска писменост во Македонија. Напишете водич за наставници во основните и средните училишта за поучување медиумска писменост. Водичот треба да вклучи: дефиниција и важност на медиумската писменост во дигиталното доба, критичко оценување на информациите (извори, факт-чекинг, lažni вести), препознавање на дезинформации и пропаганда во македонскиот медиумски пејзаж, практични активности за секоја возрасна група (основно и средно образование), алатки за факт-чекирање достапни на македонски јазик, план за вклучување на родителите, и листа на организации кои нудат поддршка за медиумска писменост во Македонија (МИМ, Метаморфозис). Пишувајте практично и со конкретни примери.","tags":["media-literacy","education","journalism","digital"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-46","title":"Развој на програма за менторство во бизнисот","prompt":"Вие сте бизнис ментор и организациски развивач со долгогодишно искуство во македонскиот деловен свет. Напишете детален план за воспоставување на програма за бизнис менторство во рамките на стопанска комора или бизнис асоцијација во Македонија. Планот треба да опфати: цели и очекувани резултати на програмата, критериуми за избор на ментори и менторирани, процес на спарување ментор-менториран, структура на менторскиот процес (фреквенција, теми, методи), обука на менторите, систем за следење на напредокот и евалуација, промоција и регрутирање на учесници, одржливост на програмата по завршувањето на иницијалниот грант, и примери на успешни програми за менторство во регионот. Вклучете конкретни алатки и темплати за менторски сесии.","tags":["mentorship","business","entrepreneurship","development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-47","title":"Правен водич за интелектуална сопственост во Македонија","prompt":"Вие сте правник специјализиран за интелектуална сопственост со искуство во македонскиот и EU правен систем. Напишете практичен водич за заштита на интелектуалната сопственост за македонски бизниси и творечки работници. Водичот треба да опфати: видови на права за интелектуална сопственост (авторски права, патенти, трговски марки, дизајн) и нивна регистрација во Македонија, Државниот завод за индустриска сопственост — процедури и трошоци, заштита на IP во EU (единствен патент, EU трговска марка, Hague систем), нарушување на права и правни лекови (граѓански и кривични постапки), посебни аспекти за дигитален бизнис (заштита на софтвер, домени, содржина), меѓународна заштита (PCT патенти, Мадридскиот систем за трговски марки), и практични совети за стартапи и мали компании. Вклучете конкретни примери на македонски компании со заштитени IP.","tags":["intellectual-property","legal","business","innovation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-48","title":"Стратегија за развој на граѓанско општество","prompt":"Вие сте консултант за граѓанско општество и демократски развој со искуство во Македонија и Западен Балкан. Напишете стратегија за зајакнување на граѓанскиот сектор во Македонија и негова поголема влога во процесот на европска интеграција. Стратегијата треба да опфати: анализа на тековната состојба на граѓанскиот сектор (број на организации, финансирање, влијание), предизвиците (ограничен простор за граѓанско општество, финансиска зависност, поларизација), придонесот на НВО во пристапниот процес (мониторинг, застапување, имплементација), модели за финансиска одржливост (социјално претпријатие, државно финансирање, странски донатори), изградба на коалиции и мрежи, дигитализација на НВО, и препораки за институционален дијалог меѓу власта и граѓанскиот сектор.","tags":["civil-society","ngo","democracy","eu-integration"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-49","title":"Финансиско образование за македонска публика","prompt":"Вие сте финансиски едукатор и советник специјализиран за финансиска писменост на граѓаните во Македонија. Напишете водич за лично финансиско управување наменет за млади возрасни (25-35 години) во Македонија. Водичот треба да опфати: основи на лично буџетирање (методот 50/30/20 прилагоден за македонски просечна плата), управување со долгови (потрошувачки кредити, картички) и стратегии за нивно намалување, штедење и вонредни фондови (колку, каде, кога), инвестициски можности достапни во Македонија (банкарски депозити, државни обврзници, акции, инвестициски фондови), купување на недвижност — предности, ризици и финансирање, пензиско штедење — задолжително и доброволно, даночни обврски на физичките лица, и дигитални алатки за управување со лични финансии. Пишувајте практично, без жаргон.","tags":["financial-literacy","personal-finance","education","youth"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-50","title":"Стратегија за поврзување на универзитет со индустријата","prompt":"Вие сте консултант за иновации и трансфер на технологии со искуство во академско-индустриски партнерства во Македонија. Напишете стратегија за зајакнување на соработката меѓу македонските универзитети и приватниот сектор. Стратегијата треба да опфати: анализа на тековниот јаз помеѓу академскиот и деловниот свет во Македонија, модели на соработка (практична настава, истражувачки проекти, spin-off компании, трансфер на технологии), правна рамка за комерцијализација на универзитетски истражувања, Технолошки развоен парк Скопје — улога и можности, финансиски инструменти (ХОРИЗОНТ Европа, Иновациски ваучери), практики за размена на кадар меѓу академијата и индустријата, и студии на случај на успешни академско-индустриски партнерства во регионот. Наведете конкретни препораки за Министерството за образование.","tags":["education","innovation","university","industry"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-51","title":"Маркетинг за македонски производи со географска ознака","prompt":"Вие сте специјалист за маркетинг на прехранбени производи и географски ознаки со искуство во балканскиот контекст. Напишете маркетинг стратегија за промоција на македонски производи со заштитена географска ознака или ознака за потекло — Охридска пастрмка, Тетовски грав, Тиквешко вино, Кавадаречки грозје. Стратегијата треба да опфати: вредноста на географски ознаки за потрошувачите и производителите, брендирање и пакување за различни пазари (домашен, регионален, EU), дигитален маркетинг план (раскажување на приказни, визуелна содржина, онлајн продажба), настап на специјализирани саеми (Sial Paris, Anuga Köln), дистрибутивни канали за EU пазарите, соработка со гастрономски новинари и food-блогери, и план за заштита на географските ознаки во EU.","tags":["food","branding","geographical-indication","export"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-52","title":"Водич за јавна политика и застапување","prompt":"Вие сте аналитичар за јавни политики со искуство во македонскиот политички систем и процес на донесување одлуки. Напишете водич за граѓански организации и стопански комори за ефективно застапување и влијание врз јавните политики во Македонија. Водичот треба да опфати: разбирање на процесот на донесување одлуки во Македонија (Влада, Собрание, регулаторни тела), идентификација на клучните чинители и нивните интереси, стратегии за застапување (лобирање, медиумска застапеност, истражување и документи за политики), изработка на политички извештај (policy brief) — структура и јазик, изградба на коалиции, комуникација со медиумите, мерење на успехот на застапувањето, и правна рамка за лобирање и застапување во Македонија.","tags":["policy","advocacy","civil-society","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-53","title":"Стратегија за развој на ромска заедница","prompt":"Вие сте консултант за социјална инклузија и развој на маргинализирани заедници со искуство во работа со ромските заедници во Македонија. Напишете стратегија за социо-економска инклузија на ромската заедница во Македонија. Стратегијата треба да опфати: анализа на тековната ситуација (образование, вработеност, домување, здравство), правна рамка и политики за инклузија (Декада на Рома, национална стратегија), приоритетни интервенции (предучилишно образование, стручно образование, пристап до пазарот на труд), финансирање преку EU фондови и национален буџет, вклучување на ромските организации и лидери, борба против дискриминацијата и подигање на свесноста, и примери на успешни интервенции од регионот (Бугарија, Србија). Пишувајте со почит и избегнувајте стереотипи.","tags":["inclusion","roma","social-policy","community"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-54","title":"Анализа на македонскиот пазар на недвижности","prompt":"Вие сте аналитичар на пазарот на недвижности со долгогодишно искуство во Македонија и регионот. Напишете сеопфатна анализа на македонскиот пазар на станбени и деловни недвижности. Анализата треба да опфати: тековни цени на недвижности по региони (Скопје, Охрид, Битола, Тетово), трендови во понудата и побарувачката, фактори кои влијаат на цените (миграција, дијаспора, економски раст), пристапност на станбени кредити и нивни услови, регулаторна рамка за промет на недвижности, ризици и можности за инвеститори, споредба со регионалните пазари (Белград, Тирана, Загреб), специфики на пазарот на туристички недвижности (Охрид), и прогноза за следните 3 години. Базирајте се на расположиви податоци и аналитички пристап.","tags":["real-estate","investment","economics","market-analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-55","title":"Обука за лидерство за македонски менаџери","prompt":"Вие сте тренер за лидерство и организациски развој со искуство во работа со македонски менаџери на различни нивоа. Напишете програма за обука за лидерство наменета за менаџери на средно ниво во македонски компании. Програмата треба да опфати: современи теории за лидерство прилагодени за македонскиот контекст, разлики помеѓу менаџментот и лидерството, изградба на тимска работа во хиерархиска организациска култура, мотивирање на вработените (теории и практики), управување со конфликти и тешки разговори, стратешко размислување и донесување одлуки, дигитално лидерство и управување со далечински тим, и 15 практични вежби и симулации. Земете го предвид специфичниот македонски организациски контекст и културните норми на работното место. Програмата да биде за 3-дневна обука.","tags":["leadership","training","management","hr"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-56","title":"Водич за верификација на факти на македонски јазик","prompt":"Вие сте новинар и медиумски аналитичар специјализиран за факт-чекинг и борба против дезинформации во Македонија. Напишете практичен водич за верификација на факти наменет за новинари, едукатори и активни граѓани. Водичот треба да опфати: методологија за верификација на информации (SIFT метода, латерално читање), алатки за верификација на слики и видеа (TinEye, InVID, Google Reverse Image Search), проверка на извори и автентичноста на веб-страници, верификација на изјави на политичари и јавни личности, специфики на македонскиот медиумски пејзаж и познати извори на дезинформации, организации за факт-чекинг во Македонија и регионот (Vistinomer, BIRN), и практични примери на верификирани и демантирани вести во Македонија. Пишувајте јасно и практично.","tags":["fact-checking","media","journalism","disinformation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-57","title":"Стратегија за развој на социјални претприемачи","prompt":"Вие сте советник за иновации и општествено претприемаштво со искуство во Македонија. Напишете програма за поддршка на социјалните иноватори и претприемачи во Македонија. Програмата треба да опфати: дефиниција на социјалното претприемаштво и неговите специфики во македонскиот контекст, мапирање на социјалните потреби кои можат да бидат адресирани преку пазарот, бизнис модели за социјални претпријатија (B Corporation, кооперативи, добротворни тргувачи), мерење на социјалното влијание (Social Return on Investment), акселератори и инкубатори достапни за социјални претприемачи во Македонија, финансирање (impact investing, хибридно финансирање, социјални обврзници), примери на успешни социјални иноватори во регионот, и препораки за развој на екосистем за социјално претприемаштво. Наменето за организации кои сакаат да развијат таква програма.","tags":["social-entrepreneurship","innovation","community","development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-58","title":"Анализа на македонскиот земјоделски сектор","prompt":"Вие сте агроекономист со длабоко познавање на македонскиот земјоделски сектор и EU земјоделската политика. Напишете сеопфатна анализа на состојбата и перспективите на македонскиот земјоделски сектор во контекст на EU пристапувањето. Анализата треба да опфати: структура на земјоделскиот сектор (површини, сопственост, производство по сектори), придонесот на земјоделството во БДП и вработеноста, конкурентност на македонските земјоделски производи на EU пазарот, предизвици при усогласувањето со EU регулативите (фитосанитарни, ветеринарни, стандарди за квалитет), влијанието на EU заедничката земјоделска политика (CAP) врз македонското земјоделство по пристапувањето, можности и закани за македонските земјоделци, препораки за реструктуирање и модернизација, и план за зголемување на органското производство.","tags":["agriculture","economics","eu-integration","rural-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-59","title":"Стратегија за развој на спортски туризам","prompt":"Вие сте консултант за спортски туризам со искуство во организирање на меѓународни спортски настани во Македонија. Напишете стратегија за развој на спортскиот туризам во Македонија. Стратегијата треба да опфати: анализа на постоечките спортски ресурси и инфраструктура (скијачки центри, планински патеки, велосипедски рути, спортски сали), потенцијал за привлекување на странски спортски тимови за подготовки (зима, есен), организирање на меѓународни спортски натпревари и нивниот туристички мултипликатор, маркетинг кон спортски клубови и организации, партнерства со национални спортски федерации, пакети за спортски туризам (планински велосипедизам, трчање, пливање во Охрид), и финансиски план и ROI анализа. Вклучете конкретни можности по спортски дисциплини.","tags":["sports-tourism","tourism","events","regional-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-60","title":"Водич за дигитален маркетинг за македонски МСП","prompt":"Вие сте дигитален маркетинг стратег специјализиран за мали и средни претпријатија во Македонија. Напишете практичен водич за МСП кои сакаат да изградат ефективно дигитално присуство со ограничен буџет. Водичот треба да опфати: основи на дигиталниот маркетинг прилагодени за македонскиот пазар (навики на потрошувачите, платформи), изградба на веб-страница (препораки за локални и меѓународни платформи, трошоци), Facebook и Instagram маркетинг за македонска публика (содржина, огласи, буџет), Google My Business и локален SEO, е-маил маркетинг (листи, автоматизација, мерење), TikTok за помлади публики, управување со репутацијата онлајн, мерење на резултатите (Google Analytics, Facebook Insights), и месечен маркетинг план со буџет од 200-500 евра. Вклучете конкретни примери на македонски брендови со успешни дигитални кампањи.","tags":["digital-marketing","sme","social-media","business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-61","title":"Правен водич за заштита на потрошувачи во Македонија","prompt":"Вие сте правник специјализиран за заштита на потрошувачи со искуство во македонскиот и EU правен систем. Напишете практичен водич за правата на потрошувачите при купување производи и услуги во Македонија. Водичот треба да опфати: законска рамка (Закон за заштита на потрошувачи и неговото усогласување со EU), права при купување во физичка продавница (гаранција, рекламации, рок на враќање), права при онлајн купување (право на отказ, испорака, повраток), права при купување на услуги (договори, откажување, компензации), заштита при агресивни и нечесни трговски практики, постапки за поднесување поплаки (трговец, Државен пазарен инспекторат, суд), алтернативно решавање на потрошувачки спорови, и права при патување (авиокомпании, туристички пакети, хотели). Пишувајте јасно, со конкретни примери.","tags":["consumer-rights","legal","protection","citizens"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-62","title":"Стратегија за управување со кризна ситуација","prompt":"Вие сте консултант за кризен менаџмент со искуство во работа со јавни институции и компании во Македонија. Напишете стратегија за управување со кризни ситуации за средно претпријатие со 200 вработени. Стратегијата треба да опфати: типологија на кризи и нивни специфики (производна, репутациска, финансиска, природна катастрофа), принципи на кризен менаџмент (брзина, транспарентност, одговорност), воспоставување на кризен тим и дефинирање на улоги и одговорности, изработка на план за кризна комуникација (внатрешна и надворешна), комуникација со медиумите во кризна ситуација (press conference, press release), управување со социјалните мрежи во криза, план за обновување на бизнисот по кризата, и вежби за симулација на кризни ситуации. Вклучете студии на случај на кризен менаџмент во македонски компании и институции.","tags":["crisis-management","communication","business","risk"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-63","title":"Водич за стручно образование и обука во Македонија","prompt":"Вие сте образовен политичар специјализиран за стручното образование и обука (СОО) во Македонија. Напишете сеопфатен водич за реформата на стручното образование во Македонија согласно европските стандарди (EQF, ECVET). Водичот треба да опфати: тековната состојба на системот за стручно образование (профили, школи, квалификации), јазот помеѓу образованието и пазарот на труд, европска рамка за квалификации и нејзината имплементација во Македонија, дуалното образование — германскиот модел и неговата применливост во македонски услови, примери на успешни реформи на СОО во Хрватска и Словенија, препораки за вклучување на работодавачите во дизајнирање на програмите, финансирање на реформите (ИПА, светска банка, TVET), и мерки за зголемување на атрактивноста на стручното образование кај младите.","tags":["vocational-education","reform","youth","education"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-64","title":"Развој на франшизен бизнис во Македонија","prompt":"Вие сте консултант за франшизни бизниси со искуство на балканскиот пазар. Напишете водич за претприемачи кои сакаат да купат или да ја прошират постоечката франшиза на македонскиот пазар. Водичот треба да опфати: предности и ризици на франшизниот модел наспроти самостоен бизнис, процес на избор на франшиза (due diligence, анализа на договорот), правна рамка за франшизни договори во Македонија, проценка на франшизниот пазар во Македонија (кои сектори се развиени: угостителство, услуги, малопродажба), финансирање на купување на франшиза (банкарски кредити, лизинг), преговарање со матична компанија за услови прилагодени за македонскиот пазар, оперативни предизвици (добавување, маркетинг, обука), и список на домашни и странски франшизи достапни на македонскиот пазар.","tags":["franchise","business","entrepreneurship","retail"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-65","title":"Стратегија за развој на планинскиот туризам","prompt":"Вие сте консултант за планински туризам со искуство во Македонија и алпскиот регион. Напишете стратегија за развој на планинскиот туризам на Шар Планина и Маврово. Стратегијата треба да опфати: инвентаризација на постоечката инфраструктура и нејзиниот квалитет (ски лифтови, патеки, сместување), анализа на конкуренцијата (Попова Шапка vs косовски и бугарски скијалишта), сегментација на целниот пазар (домашни туристи, балкански туристи, западноевропски посетители), продолжување на туристичката сезона (лето, есен активности), инвестициски потреби и приоритети, финансирање преку ИПАРД, ИПА и приватни инвеститори, одржливост и заштита на планинската средина, и план за промоција на Македонија како зимска туристичка дестинација. Вклучете конкретни препораки за Маврово и Попова Шапка.","tags":["mountain-tourism","winter-sports","tourism","regional-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-66","title":"Водич за управување со мал хотел или пансион","prompt":"Вие сте хотелски консултант со искуство во управување со мали хотели и пансиони во туристичките дестинации во Македонија. Напишете практичен водич за сопственици на мали хотели и пансиони (10-30 соби) во Македонија. Водичот треба да опфати: регистрација и категоризација на угостителски објект (постапка, барања, трошоци), стандарди на услуга и управување со квалитетот, управување со резервации (PMS системи, Booking.com, Airbnb, директни резервации), ценовна стратегија и динамично ценење, маркетинг за мал хотел (веб-страница, социјални мрежи, TripAdvisor), управување со персоналот (рецепција, домаќинство, угостителство), финансиско управување (буџет, трошоци, приходи), и план за подобрување на рецензиите и зголемување на оценките. Дадете практични примери прилагодени за македонскиот туристички контекст.","tags":["hospitality","tourism","small-business","management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-67","title":"Анализа на македонскиот образовен систем","prompt":"Вие сте образовен аналитичар со специјализација за образовни политики во Западен Балкан. Напишете аналитички документ за состојбата на македонскиот образовен систем и препораки за реформи. Документот треба да опфати: структурата на образовниот систем (предучилишно, основно, средно, високо), клучни показатели за квалитет (PISA резултати, стапки на завршување, функционална писменост), анализа на предизвиците (раздвоеноста по етнички линии, квалитет на наставата, застарена инфраструктура), финансирање на образованието (% од БДП, ефикасност на трошењето), EU образовни политики и нивната примена во Македонија (Bologna процес за високото образование), компаративна анализа со образовни системи во регионот, и приоритетни реформи со временска рамка и потребни ресурси. Документот да биде базиран на расположиви статистички податоци.","tags":["education","reform","policy","analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-68","title":"Стратегија за управување со водните ресурси","prompt":"Вие сте консултант за управување со водни ресурси и животна средина со искуство во регионот на Западен Балкан. Напишете стратегија за одржливо управување со водните ресурси во Македонија, земајќи ги предвид климатските промени и зголемениот притисок на водите. Стратегијата треба да опфати: состојба на водните ресурси во Македонија (реки, езера, подземни води), предизвиците (загадување, прекумерна употреба, климатски промени), правна рамка и усогласување со EU Рамковната директива за води, план за заштита на Охридското Езеро (природно и светско наследство на УНЕСКО), стратегија за наводнување во земјоделството, управување со отпадни води и пречистувачки станици, и меѓународна соработка за прекугранични водни тела (Дојранско Езеро, Вардар/Аксиос). Вклучете финансиски аспекти и достапни EU инструменти.","tags":["water-management","environment","sustainability","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-69","title":"Водич за основање на кооператива во Македонија","prompt":"Вие сте правник и консултант специјализиран за кооперативното право и земјоделски кооперативи во Македонија. Напишете практичен водич за земјоделци и мали производители кои сакаат да основаат земјоделска кооператива. Водичот треба да опфати: правна рамка за кооперативи во Македонија (Закон за земјоделски задруги), предности на кооперативниот модел (заеднички набавки, заедничка продажба, поголема преговарачка моќ), чекор-по-чекор процедура за основање (статут, регистрација, органи), управување со кооперативата (скупштина, управен одбор, надзорен одбор), финансиски аспекти (членски придонеси, поделба на добивката, пристап до кредити), државна поддршка за кооперативи, примери на успешни земјоделски кооперативи во Македонија, и предизвиците и начини за нивно надминување. Пишувајте практично, за луѓе без правно образование.","tags":["cooperative","agriculture","legal","rural-development"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-70","title":"Стратегија за развој на здравствениот туризам","prompt":"Вие сте консултант за здравствен и велнес туризам со искуство во Македонија и регионот. Напишете стратегија за развој на здравствениот и велнес туризам во Македонија, со акцент на природните ресурси (термални извори, планински воздух, чисти езера). Стратегијата треба да опфати: инвентаризација на природните здравствени ресурси (бањите Банско, Дебарски Бањи, Катланово, Негорски Бањи), анализа на меѓународниот пазар за здравствен туризам, позиционирање на Македонија во регионалната конкуренција (Словенија, Австрија, Србија), инвестиции потребни за развој на капацитетите (медицински апарати, велнес центри), регулаторна рамка за здравствен туризам, партнерства со здравствени осигурувања, дигитален маркетинг за привлекување на меѓународни здравствени туристи, и план за сертификација на квалитетот. Дадете конкретни приоритети за инвестирање.","tags":["health-tourism","wellness","tourism","investment"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-71","title":"Управување со мултигенерациски тим","prompt":"Вие сте организациски психолог и консултант за управување со луѓе со искуство во македонски и меѓународни компании. Напишете практичен водич за менаџери кои управуваат со тим кој вклучува вработени од различни генерации — бејби бумери, Генерација Х, милениалци и Генерација Z — во македонски компании. Водичот треба да опфати: разбирање на генерациските разлики во работните вредности, очекувања и стилови на комуникација, стратегии за мотивирање на секоја генерација, управување со конфликти помеѓу генерации, пренос на знаење и ментор-програми меѓу генерациите, прилагодување на стилот на водење за секоја генерација, дигитализацијата и предизвиците за постарите вработени, и изградба на инклузивна тимска култура. Вклучете конкретни примери од македонскиот деловен контекст и практични алатки.","tags":["hr","management","generational","workplace"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-72","title":"Анализа за развој на македонскиот финтек сектор","prompt":"Вие сте финансиски аналитичар специјализиран за финтек иновации во малите пазари на Источна Европа. Напишете аналитичка студија за потенцијалот и предизвиците за развој на финтек секторот во Македонија. Студијата треба да опфати: тековна состојба на финтек секторот во Македонија (компании, производи, регулатива), регулаторна рамка и нејзино усогласување со EU PSD2 директивата, пречки за развој (мал пазар, ограничен пристап до капитал, регулаторни бариери), можности (висока пенетрација на смартфони, дијаспорски дознаки, необслужено население), примери на успешни финтек компании во регионот (Грција, Романија, Бугарија), препораки за регулаторен sandbox и поддршка на иновации, и стратегија за позиционирање на Македонија како финтек хаб за регионот. Базирајте се на конкретни примери и податоци.","tags":["fintech","technology","finance","innovation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-73","title":"Стратегија за комуникација на научни резултати","prompt":"Вие сте научник и комуникатор на науката со искуство во популаризација на научни истражувања во Македонија. Напишете стратегија за ефективна комуникација на научни и истражувачки резултати кон пошироката јавност во Македонија. Стратегијата треба да опфати: анализа на јазот помеѓу науката и јавноста во Македонија, принципи на ефективна научна комуникација, различни канали и формати (медиуми, социјални мрежи, научни кафеа, отворени денови), пишување на разбирливи научни текстови за непрофесионална публика, соработка со новинари и уредници, улогата на научниците во борбата против дезинформации (вакцини, климатски промени), изградба на научна заедница на Македонски јазик онлајн, и институционална поддршка за популаризација на науката. Вклучете добри практики и примери од македонски и регионален контекст.","tags":["science-communication","research","education","media"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-74","title":"Водич за деловно преговарање во македонски контекст","prompt":"Вие сте преговарач и консултант за бизнис комуникации со долгогодишно искуство во македонски и меѓународен деловен контекст. Напишете практичен водич за ефективно деловно преговарање за македонски бизнисмени кои преговараат и со домашни и со странски партнери. Водичот треба да опфати: разбирање на македонската деловна культура и нејзините специфики при преговарање (улогата на довербата, личните односи, хиерархијата), принципи на принципиелно преговарање (Harvard метода), подготовка за преговори (BATNA, цели, концесии), тактики и контра-тактики при преговарање, преговарање со EU и западни партнери — очекувани разлики, комуникациски стилови (директна vs индиректна комуникација), управување со застој во преговорите, и специфики на преговарање за различни ситуации (цена, договор, партнерство). Вклучете вежби и примери.","tags":["negotiation","business","communication","culture"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-75","title":"Стратегија за развој на културен туризам","prompt":"Вие сте консултант за управување со културното наследство и туризам со искуство во Македонија. Напишете стратегија за развој на културниот туризам во Скопје и неговата поширока околина. Стратегијата треба да опфати: инвентаризација на културните атракции (археолошки наоѓалишта, цркви и џамии, музеи, стар Скопски Базар), анализа на тековните туристички текови и нивните профили, развој на тематски туристички рути (Македонска антика, Отоманско наследство, Комунистичка архитектура, Модерна уметност), дигитализација на културното наследство (виртуелни тури, AR апликации), соработка со УНЕСКО и меѓународни организации за наследство, финансирање на реставрација и зачувување на наследството, и маркетинг план за привлекување на меѓународни културни туристи. Земете ги предвид и чувствителностите поврзани со мешовитото наследство на градот.","tags":["cultural-tourism","heritage","tourism","skopje"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-76","title":"Водич за менаџмент на промени во организација","prompt":"Вие сте консултант за организациски развој и управување со промени со искуство во македонски јавни институции и компании. Напишете практичен водич за раководители кои треба да спроведат значајни организациски промени во македонски контекст. Водичот треба да опфати: разбирање на отпорот кон промени и неговите причини во македонска организациска култура, Kotter-овата методологија за управување со промени и нејзина примена, изградба на коалиција за промени и идентификација на лидери за промени, комуникација на промените (кога, на кој начин, со кого), управување со несигурноста и анксиозноста на вработените, мерење на напредокот и прилагодување на планот, институционализација на промените (нова организациска культура), и студии на случај на успешни и неуспешни организациски промени во македонски компании и институции.","tags":["change-management","organization","leadership","management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-77","title":"Стратегија за развој на аграрен туризам","prompt":"Вие сте консултант за рурален и аграрен туризам со искуство во Македонија и регионот. Напишете бизнис стратегија за земјоделско стопанство во Македонија кое сака да се диверзифицира со воведување на аграрен туризам. Стратегијата треба да опфати: анализа на ресурсите на стопанството (површини, производи, локација, природни атракции), дизајн на аграрно-туристички производи (бербарски тури, работилници за правење сирење или ракија, ноќевање, фарм-то-table искуство), потребни инвестиции и потребни дозволи и категоризации, маркетинг (директна продажба, соработка со туроператори, AirBnB, Booking), ценовна стратегија и финансиски проекции, ИПАРД III финансирање за диверзификација, и управување со сезоналноста на бизнисот. Вклучете конкретни примери на успешни агро-туристички стопанства во Македонија и регионот.","tags":["agro-tourism","agriculture","rural-development","tourism"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-78","title":"Анализа на јавни финансии на македонска општина","prompt":"Вие сте финансиски аналитичар специјализиран за јавни финансии и фискална децентрализација во Македонија. Направете анализа на состојбата на јавните финансии на следната општина: [Наведете го името на општината и нејзините основни карактеристики — број на жители, економска структура]. Анализата треба да опфати: структура на приходи (сопствени приходи, блок дотации, наменски дотации, европски фондови), структура на расходи по функции, показатели за фискална одржливост, споредба со слични општини во Македонија, анализа на општинскиот долг и обврски, идентификација на можности за зголемување на сопствените приходи, препораки за подобрување на буџетирањето и трошењето, и план за среднорочна фискална рамка. Засновајте ја анализата на методологијата на Министерството за финансии.","tags":["public-finance","local-government","budget","analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-79","title":"Водич за вработување на странци во Македонија","prompt":"Вие сте правник специјализиран за трудово и миграциско право со искуство во Македонија. Напишете комплетен водич за компании кои сакаат да вработат странски државјани во Македонија. Водичот треба да опфати: правна рамка за вработување на странци (Закон за странци, Закон за работни односи), типови на дозволи за работа и нивно добивање (квота систем, исклучоци, ICT дозволи), постапка и документи потребни за добивање на работна виза, регистрација на странец кај надлежните органи, права и обврски на странскиот работник, посебни правила за државјани на земји кои имаат безвизен режим со Македонија, даночни импликации за работодавачот и работникот, и практични совети за релокација на странски вработени (сместување, школи, банка). Вклучете временски рокови и трошоци.","tags":["hr","legal","immigration","employment"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-80","title":"Стратегија за развој на македонски стартап екосистем","prompt":"Вие сте претприемачки еко-систем стратег со искуство во изградба на стартап екосистеми во земјите во развој. Напишете стратегија за изградба на конкурентен стартап екосистем во Македонија. Стратегијата треба да опфати: анализа на тековниот екосистем (актери, силни и слаби страни, финансирање), компаративна анализа со успешни регионални екосистеми (Естонија, Грузија, Романија), предуслови за развој (регулаторна рамка, даночни олеснувања, образование, капитал), изградба на инкубатор/акселератор мрежа (УКИМ TDP, Skopje Innovation Hub), привлекување на ризичен капитал и angel investors, програми за поврзување со глобалниот стартап екосистем (Silicon Valley, Берлин, Лондон), вклучување на дијаспората во развојот на екосистемот, и мерење на успехот (инвестиции, извоз на технологија, нови работни места). Наведете конкретни препораки за Влада и приватен сектор.","tags":["startup","ecosystem","technology","entrepreneurship"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-81","title":"Анализа за положбата на жените на пазарот на труд","prompt":"Вие сте истражувач за родова рамноправност и пазар на труд со искуство во Македонија. Напишете аналитички извештај за положбата на жените на пазарот на труд во Македонија и препораки за подобрување. Извештајот треба да опфати: клучни статистички показатели (стапка на активност, невработеност, разлика во плати по пол), сектори со доминантно женска работна сила и нивните карактеристики, предизвиците (неплатен семеен труд, дискриминација, стаклен таван), правна рамка за рамноправност на половите (Закон за еднакви можности, EU директиви), влијанието на мајчинството врз кариерата, предизвиците за жени-претприемачи, добри практики на компании во Македонија кои промовираат родова рамноправност, и конкретни препораки за политики за зголемување на женската економска партиципација.","tags":["gender-equality","labor-market","policy","women"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-82","title":"Водич за развој на личен бренд на македонски јазик","prompt":"Вие сте консултант за личен бренд и дигитална присутност со искуство во работа со македонски бизнис лица и јавни личности. Напишете практичен водич за изградба на личен бренд за македонски претприемачи, менаџери и стручни лица. Водичот треба да опфати: дефиниција на личниот бренд и неговото значење во македонскиот деловен контекст, идентификување на единствената вредносна понуда (личен USP), изградба на дигитално присуство (LinkedIn за B2B, Instagram за B2C, YouTube за едукација), создавање на содржина на македонски јазик — теми, формати, фреквенција, говорење на настани и изградба на авторитет во стручната заедница, управување со личниот бренд во кризни ситуации, мерење на влијанието на личниот бренд, и практични примери на успешни лични брендови во Македонија. Пишувајте практично и охрабрувачки.","tags":["personal-branding","digital","marketing","career"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-83","title":"Стратегија за управување со синџирот на снабдување","prompt":"Вие сте консултант за логистика и синџир на снабдување со искуство во производствени компании во Македонија. Напишете стратегија за оптимизација на синџирот на снабдување за македонска производствена компанија со 120 вработени која извезува во EU. Стратегијата треба да опфати: анализа на тековниот синџир на снабдување (добавувачи, производство, дистрибуција, клиенти), идентификација на слабости и ризици (зависност од единечни добавувачи, долги испорачни рокови, трошоци на залихи), стратегии за диверзификација на добавувачи, имплементација на lean manufacturing принципи во македонски услов, логистика и царина во трговијата со EU (правила за потекло на стоки, АТР документи), дигитализација на синџирот (ERP, track and trace), и план за зголемување на отпорноста на синџирот во услови на кризи (COVID урок). Вклучете конкретни KPI за мерење на ефикасноста.","tags":["supply-chain","logistics","manufacturing","operations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-84","title":"Водич за дигитализација на образовниот процес","prompt":"Вие сте образовен технолог и консултант за дигитална трансформација на образованието со искуство во македонски училишта. Напишете практичен водич за директори и наставници во македонски основни и средни училишта за воведување на дигитални алатки во наставниот процес. Водичот треба да опфати: проценка на тековниот дигитален капацитет на училиштето (опрема, интернет, вештини на наставниците), приоритетни дигитални алатки за настава (Google Classroom, Microsoft Teams, Kahoot, Canva Education), методологија за хибридна и онлајн настава, создавање на дигитална содржина на македонски јазик, управување со личните податоци на учениците (GDPR), поддршка за ученици со ограничен пристап до технологија, мерење на ефективноста на дигиталната настава, и финансирање (MKT, Министерство за образование, EU грантови за дигитализација на образованието). Пишувајте практично со конкретни примери.","tags":["education","digital","technology","schools"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-85","title":"Анализа на потенцијалот за обновлива енергија во Македонија","prompt":"Вие сте енергетски аналитичар специјализиран за обновливи извори на енергија со искуство во Западен Балкан. Напишете сеопфатна анализа на потенцијалот за производство на обновлива енергија во Македонија. Анализата треба да опфати: преглед на тековната енергетска ситуација (производство, потрошувачка, увоз, тарифи), потенцијал за сонечна енергија по региони, потенцијал за ветерна енергија, постоечките хидроелектрани и потенцијал за нови мали хидро-централи, геотермален потенцијал, регулаторна рамка и пречките за развој на обновливи извори, механизми за поддршка (feed-in тарифи, премии, аукции), инвестициски можности и финансирање (ЕБРД, ЕИБ, IFC), и патоказ за достигнување на EU целите за обновлива енергија. Базирајте се на достапни ресурсни карти и официјални извори.","tags":["renewable-energy","environment","investment","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},
    {"id":"mk-86","title":"Стратегија за развој на конгресен туризам во Скопје","prompt":"Вие сте консултант за MICE (Meetings, Incentives, Conferences, Exhibitions) туризам со искуство во регионот. Напишете стратегија за развој на конгресниот туризам во Скопје. Стратегијата треба да опфати: анализа на тековниот конгресен капацитет во Скопје (хотели со конгресни сали, Конгресниот центар), конкурентна позиција наспроти Белград, Тирана, Сараево и Приштина, целни сегменти на конгресниот туризам (меѓувладини, научни, корпоративни, асоцијациски настани), стратегија за привлекување на меѓународни конгреси и конференции, потребни инвестиции во инфраструктура, улогата на Скопски Конгресен Биро, маркетинг на меѓународни платформи (ICCA, MPI), соработка со авиокомпании за зголемување на директните летови, и економски мултипликатор на конгресниот туризам. Дадете реалистична проценка на потенцијалот.","tags":["mice-tourism","conferences","skopje","tourism"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-87","title":"Водич за управување со непрофитна организација","prompt":"Вие сте менаџер на непрофитни организации со повеќе од 12 години искуство во македонскиот граѓански сектор. Напишете практичен водич за управување со непрофитна организација (НВО) во Македонија. Водичот треба да опфати: правна рамка за НВО (Закон за здруженија и фондации, регистрација, промена на статут), добро управување (Управен одбор, Извршен директор, советодавни тела), финансиско управување (буџетирање, сметководство, ревизија, известување до донатори), управување со проекти и персонал, правила за спречување на перење пари и финансирање тероризам (ФАТФ барања за НВО), транспарентност и отчетност (јавни извештаи, регистри), стратешко планирање за НВО, и предизвиците и добрите практики за финансиска одржливост на македонски НВО.","tags":["ngo","management","civil-society","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-88","title":"Стратегија за развој на македонскиот извозен капацитет","prompt":"Вие сте трговски советник специјализиран за развој на извозниот капацитет на малите економии во Источна Европа. Напишете национална стратегија за зголемување на извозниот капацитет на македонските МСП. Стратегијата треба да опфати: дијагноза на тековниот извоз (структура, пазари, производи, вредносни синџири), пречки за извоз кај МСП (информации, стандарди, логистика, финансирање, јазик), програми за поддршка на извоз (АСПАЛТ, Агенција за промоција на претприемаштвото, Стопанска комора), дигитализација на извозот (платформи за B2B, е-трговија), соработка со македонските дипломатски мисии за комерцијална промоција, мерки за подобрување на стандардите за квалитет и сертификација, и план за поддршка на прв извоз за компании кои никогаш не извезувале. Вклучете конкретни цели и мерки за успех.","tags":["export","trade","sme","international-business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-89","title":"Водич за правно уредување на семеен бизнис","prompt":"Вие сте правник и бизнис советник специјализиран за семејни претпријатија со искуство во Македонија. Напишете практичен водич за правно уредување на односите во семеен бизнис и подготовка за сукцесија. Водичот треба да опфати: специфики на семејниот бизнис во македонски контекст (неформален почеток, управување, конфликти), правни форми соодветни за семеен бизнис и нивни предности и недостатоци, семејна конституција (family charter) — структура и значење, правила за влез и излез на членови на семејството во бизнисот, уредување на плати, поделба на добивката и реинвестирање, план за наследување на бизнисот (succession plan), улогата на надворешни менаџери и надворешен борд, управување со конфликти во семеен бизнис, и примери на успешна сукцесија во македонски семејни компании. Пишувајте практично, земајки ги предвид македонските семејни вредности.","tags":["family-business","legal","succession","sme"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-90","title":"Анализа на регулаторната рамка за странски инвестиции","prompt":"Вие сте правен и деловен советник специјализиран за привлекување на странски директни инвестиции во Македонија. Напишете аналитички документ за регулаторната рамка за странски инвестиции во Македонија наменет за странски инвеститори. Документот треба да опфати: правна рамка (Закон за трговски друштва, Закон за странски инвестиции), заштита на инвестициите (Билатерални инвестициски договори, ICSID арбитража), слободни економски зони (ТИРЗС) — поволности и услови, даночен систем — данок на добивка, ДДВ, придонеси (со споредба со регионот), системот за решавање на деловни спорови, реформи во деловното опкружување и нивниот успех (Doing Business рангирање), практични предизвици и начини за нивно надминување (бирократија, правно системот), и примери на успешни странски инвестиции во Македонија (компании, сектори, резултати).","tags":["investment","legal","fdi","business-climate"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-91","title":"Стратегија за развој на дигиталните вештини на работната сила","prompt":"Вие сте консултант за развој на работна сила и дигитални вештини со искуство во македонскиот пазар на труд. Напишете национална стратегија за развој на дигиталните вештини на работната сила во Македонија до 2030 година. Стратегијата треба да опфати: анализа на тековното ниво на дигитални вештини (DESI индекс за Македонија), дефицитот на дигитални вештини по сектори (ИТ, производство, јавен сектор, земјоделство), целни групи (работници во ризик од автоматизација, невработени, жени, постарите вработени), рамки за дигитални компетенции (EU DigComp), видови обука (bootcamps, онлајн курсеви, дуална обука), институционална рамка за имплементација (АВРМ, Министерство за образование, МКТ), финансирање (ЕСФ+, национален буџет), и систем за признавање на неформално стекнати дигитални вештини.","tags":["digital-skills","workforce","education","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-92","title":"Водич за пристап до пазарот на ЕУ за македонски извозници","prompt":"Вие сте трговски советник специјализиран за пристап на балканските земји до EU пазарот со долгогодишно практично искуство. Напишете детален водич за македонски компании кои сакаат прв пат да извезуваат своите производи во Европската унија. Водичот треба да опфати: правниот режим на трговија меѓу Македонија и EU (ССА и нивните поволности), регулаторни барања за влез во EU пазарот по производни категории (храна, текстил, машини, хемиски производи), системи за сертификација и стандарди (CE ознака, ISO, органски сертификати), царинска постапка и документи за извоз, правила за потекло на стоки и доказ за преференцијал, пронаоѓање на EU партнери и дистрибутери, финансирање на прв извоз, и листа на институции кои нудат поддршка за македонски извозници кон EU (АСПАЛТ, Стопанска комора, EU delegation Скопје).","tags":["export","eu-market","trade","business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-93","title":"Анализа и стратегија за ИКТ во јавниот сектор","prompt":"Вие сте ИКТ консултант специјализиран за дигитализација на јавниот сектор во земјите во развој. Напишете стратегија за ИКТ трансформација на јавниот сектор во Македонија за периодот 2025-2030. Стратегијата треба да опфати: состојба на дигитализацијата на јавниот сектор (е-услуги, интероперабилност, облак инфраструктура), приоритетни области за дигитализација (даноци, катастар, здравство, образование, судство), архитектура на е-влада (единствена платформа, дигитален идентитет, електронски потпис), стандарди за интероперабилност на системите, сајбер безбедност на јавните системи, финансирање и план за имплементација, управување со ИКТ проектите во јавниот сектор (честите неуспеси и лекции), и мерење на напредокот (UN e-Government индекс, EU DESI). Вклучете добри практики од регионот.","tags":["ict","digital-government","technology","public-sector"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-94","title":"Стратегија за развој на македонската дијаспора","prompt":"Вие сте аналитичар за миграција и политики за дијаспора со искуство во Македонија. Напишете стратегија за поврзување на македонската дијаспора со развојот на земјата. Стратегијата треба да опфати: профил на македонската дијаспора (број, земји на живеење, образование, професија), економски потенцијал на дијаспората (дознаки, инвестиции, пренос на знаење), институционална рамка за соработка со дијаспората (МИРСМ, општини), програми за задржување на врската со Македонија (јазични курсеви, летни школи, политички права), привлекување на дијаспорски инвестиции (информации, даночни поволности, инфраструктура), програми за привремен или траен повраток (ментор дијаспора, Brain Circulation), и дигитални платформи за поврзување. Базирајте се на примери на успешни политики за дијаспора од регионот (Ирска, Грузија).","tags":["diaspora","migration","development","policy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-95","title":"Водич за управување со јавни настани во Македонија","prompt":"Вие сте организатор на настани со долгогодишно искуство во организирање на јавни и деловни настани во Македонија. Напишете практичен водич за организирање на јавни настани (конференции, фестивали, спортски настани) во Македонија. Водичот треба да опфати: правна регулатива за организирање јавни настани (дозволи, безбедносни планови, соодветни органи), процес на планирање и буџетирање на настан, избор и резервирање на локации во Македонија (сали, отворени простори, историски локации), договарање со добавувачи (техника, угостителство, безбедност, транспорт), маркетинг и продажба на билети (онлајн платформи достапни во Македонија), управување со настанот (персонал, логистика, контингенции), управување со медиумите и комуникација, финансиски план и фактурирање, и евалуација на настанот. Вклучете специфики за организирање настани во Скопје, Охрид и Битола.","tags":["events","management","tourism","business"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-96","title":"Анализа за вклучување на младите во политичкиот живот","prompt":"Вие сте политиколог и истражувач специјализиран за младинска политика и политичка партиципација во Западен Балкан. Напишете аналитички извештај за политичката партиципација на младите во Македонија и препораки за нејзино зголемување. Извештајот треба да опфати: тековните нивоа на политичка партиципација на младите (излезност на избори, членство во партии, граѓанско ангажирање), причини за апатијата и дистанцирањето на младите од политиката, анализа на институционалните механизми за младинска партиципација (Агенција за млади, општини, Собрание), улогата на образованието во развојот на граѓански вредности, дигиталната демократија и нејзиниот потенцијал за ангажирање на младите, добри практики за инклузија на младите во политичкиот живот од регионот и EU, и конкретни препораки за политики и програми.","tags":["youth","politics","participation","democracy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-97","title":"Стратегија за развој на планинско велосипедарство","prompt":"Вие сте консултант за активен туризам и спорт во природа со искуство во Македонија и алпскиот регион. Напишете стратегија за развој на планинско велосипедарство (mountain biking) во Македонија како туристички производ. Стратегијата треба да опфати: инвентар на тековните патеки и нивниот квалитет (Маврово, Шар Планина, Кајмакчалан, Конечко), анализа на потенцијалниот пазар (домашни и странски велосипедисти), стандарди за обележување и одржување на MTB патеки (IMBA стандарди), потребни инвестиции во инфраструктура (патеки, гардеробери, сервиси за велосипеди, сместување), обука на локалните водичи, организирање на велосипедски настани и натпревари за меѓународна привлечност, маркетинг преку специјализирани медиуми и социјални мрежи, и финансирање (ИПАРД, општини, приватни инвеститори). Вклучете конкретни предлог-рути по региони.","tags":["cycling","active-tourism","tourism","sports"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-98","title":"Водич за академско пишување на македонски јазик","prompt":"Вие сте лингвист и педагог специјализиран за академско пишување на македонски јазик со долгогодишно искуство на универзитетска настава. Напишете сеопфатен водич за студенти и истражувачи за пишување на академски трудови на македонски јазик. Водичот треба да опфати: структура на академски труд (апстракт, вовед, методологија, резултати, дискусија, заклучок, библиографија), стил и јазик во академското пишување на македонски (формален регистар, избегнување разговорни изрази), правила за цитирање и референцирање (APA, MLA, Chicago — прилагодени за македонски јазик), избегнување на плагијаризам и правилно перифразирање, граматичките особености на академскиот македонски јазик (глаголски форми, конструкции за именување поими), и прегледување и ревизија на академски текст. Вклучете конкретни примери на добро и лошо академско пишување на македонски.","tags":["academic-writing","macedonian-language","education","research"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-99","title":"Водич за пристапност и инклузија во дигиталните услуги","prompt":"Вие сте консултант за дигитална пристапност и инклузивен дизајн со искуство во имплементација на WCAG стандардите во Македонија. Напишете практичен водич за компании и јавни институции во Македонија за обезбедување на дигитална пристапност на нивните онлајн сервиси. Водичот треба да опфати: правна рамка (EU Web Accessibility Directive, македонски закони за права на лицата со попреченост), стандарди за пристапност (WCAG 2.1 ниво АА), основни принципи на пристапен дизајн (перцептивност, оперативност, разбирливост, робустност), практични решенија за различни видови попреченост (визуелна, слушна, моторна, когнитивна), алатки за проверка на пристапноста, обука на тимовите за развој, и деловниот случај за инвестирање во пристапност. Пишувајте практично со конкретни примери применливи за македонски компании и институции.","tags":["accessibility","digital","inclusion","web"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},
    {"id":"mk-100","title":"Визија за Македонија 2035 — стратешки развој","prompt":"Вие сте стратешки плаер и футурист со длабоко познавање на македонската општествено-економска реалност и глобалните трендови. Напишете визионерски документ за Македонија 2035 — какви општествени, економски и политички трансформации се потребни и реалистични за земјата да стане просперитетна членка на ЕУ со висок стандард на живот за сите граѓани. Документот треба да опфати: глобалниот и регионален контекст во кој ќе се развива Македонија (технолошки промени, климатски промени, геополитика), визија за економскиот развој (структурна трансформација, иновации, зелена економија), визија за општествениот развој (образование, здравство, инклузија, меѓуетнички односи), визија за демократскиот развој (владеење на правото, антикорупција, медиумска слобода), улогата на членството во НАТО и EU, и конкретни стратешки приоритети за следните 10 години со одговорни актери. Пишувајте инспиративно, но реалистично и базирано на докази.","tags":["strategy","vision","development","eu-integration","macedonia"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true}
];
  __exports.macedonianPrompts = macedonianPrompts;
